-- MISSION A17 — customer documents and tenant-safe knowledge.
-- Ingestion and retrieval never touch business verification. document_chunks hold the extracted
-- text; search_vector is generated by PostgreSQL. Optional embeddings (embedding_json) are written
-- only by a reviewed, operator-configured embedding provider and are never used to invent content.
CREATE TABLE IF NOT EXISTS documents (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES identity_workspaces(id) ON DELETE CASCADE,
  name text NOT NULL,
  content_type text NOT NULL,
  size_bytes integer NOT NULL,
  sha256 text NOT NULL,
  storage_key text NOT NULL UNIQUE,
  state text NOT NULL DEFAULT 'PENDING_UPLOAD',
  extraction_code text,
  purpose text,
  uploaded_by text NOT NULL REFERENCES identity_users(id) ON DELETE CASCADE,
  retention_days integer NOT NULL DEFAULT 365,
  expires_at timestamptz,
  chunk_count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CONSTRAINT documents_state_check CHECK (state IN ('PENDING_UPLOAD', 'PROCESSING', 'AVAILABLE', 'FAILED', 'DELETED')),
  CONSTRAINT documents_size_check CHECK (size_bytes >= 0 AND size_bytes <= 10485760),
  CONSTRAINT documents_retention_check CHECK (retention_days >= 1 AND retention_days <= 3650)
);
CREATE INDEX IF NOT EXISTS documents_workspace_state_idx ON documents (workspace_id, state, created_at);
CREATE INDEX IF NOT EXISTS documents_expiry_idx ON documents (expires_at) WHERE expires_at IS NOT NULL;

CREATE TABLE IF NOT EXISTS document_chunks (
  id text PRIMARY KEY,
  document_id text NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  workspace_id text NOT NULL REFERENCES identity_workspaces(id) ON DELETE CASCADE,
  ordinal integer NOT NULL,
  page integer,
  text text NOT NULL,
  search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple', text)) STORED,
  embedding_json jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT document_chunks_ordinal_unique UNIQUE (document_id, ordinal)
);
CREATE INDEX IF NOT EXISTS document_chunks_vector_idx ON document_chunks USING GIN (search_vector);
CREATE INDEX IF NOT EXISTS document_chunks_workspace_idx ON document_chunks (workspace_id);

CREATE TABLE IF NOT EXISTS operation_documents (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES identity_workspaces(id) ON DELETE CASCADE,
  operation_id text NOT NULL,
  document_id text NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  attached_by text NOT NULL REFERENCES identity_users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT operation_documents_unique UNIQUE (operation_id, document_id)
);
CREATE INDEX IF NOT EXISTS operation_documents_operation_idx ON operation_documents (operation_id);

CREATE TABLE IF NOT EXISTS document_ingest_jobs (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES identity_workspaces(id) ON DELETE CASCADE,
  document_id text NOT NULL UNIQUE REFERENCES documents(id) ON DELETE CASCADE,
  state text NOT NULL DEFAULT 'PENDING',
  attempts integer NOT NULL DEFAULT 0,
  last_error_code text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT document_ingest_jobs_state_check CHECK (state IN ('PENDING', 'PROCESSING', 'DONE', 'FAILED'))
);
CREATE INDEX IF NOT EXISTS document_ingest_jobs_state_idx ON document_ingest_jobs (state, updated_at);

CREATE TABLE IF NOT EXISTS document_audit_events (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES identity_workspaces(id) ON DELETE CASCADE,
  document_id text,
  user_id text,
  action text NOT NULL,
  outcome text NOT NULL,
  reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT document_audit_outcome_check CHECK (outcome IN ('SUCCESS', 'DENIED', 'FAILED'))
);
CREATE INDEX IF NOT EXISTS document_audit_workspace_idx ON document_audit_events (workspace_id, created_at);
